<?php
namespace qqworld_collector\module\static_cache; class date_archive extends handler { public function make_cache($year, $month=null, $day=null) { if ($year && !$month && !$day) { $url = str_replace( home_url(), '', get_year_link($year) ); $args = 'index.php?m=' . $year; } elseif ($year && $month && !$day) { $url = str_replace( home_url(), '', get_month_link($year, $month) ); $args = 'index.php?m=' . $year . zeroise( $month, 2 ); } elseif ($year && $month && $day) { $url = str_replace( home_url(), '', get_day_link($year, $month, $day) ); $args = 'index.php?m=' . $year . zeroise( $month, 2 ) . zeroise( $day, 2 ); } $path = $this->get_path($url, $this->abspath); $respond = $this->set_pure_cache($path, $args); $page = 2; while ($respond) { $path = $this->get_path($url . 'page/' . $page, $this->abspath); $respond = $this->set_pure_cache($path, $args . "&paged={$page}"); $page++; } } } ?>